insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000995251','40000000-0000-4000-8000-000000099525','Nomeie primeiro a ideia central: Há um produto: derivar $x$ o simplifica e integrar $e^{2x}$ é direto.',1),('60000000-0000-4000-8000-000000995252','40000000-0000-4000-8000-000000099525','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000995253','40000000-0000-4000-8000-000000099525','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099525','$e^{2x}\left(\frac{x}{2}-\frac{1}{4}\right)+C$','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Há um produto: derivar $x$ o simplifica e integrar $e^{2x}$ é direto. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000995251','40000000-0000-4000-8000-000000099525','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000995252','40000000-0000-4000-8000-000000099525','Reconheça a ideia','Há um produto: derivar $x$ o simplifica e integrar $e^{2x}$ é direto.',2),('70000000-0000-4000-8000-000000995253','40000000-0000-4000-8000-000000099525','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000995254','40000000-0000-4000-8000-000000099525','Desenvolva a análise','Execute a transformação necessária e obtenha: $e^{2x}\left(\frac{x}{2}-\frac{1}{4}\right)+C$',4),('70000000-0000-4000-8000-000000995255','40000000-0000-4000-8000-000000099525','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
